lab.solution:
def can_edit(current_user_id, record):
    return current_user_id == record['learner_id']

def edit_status(current_user_id, record, status):
    if not can_edit(current_user_id, record):
        return {'ok': False, 'error': 'not_found_or_not_allowed'}
    return {'ok': True, 'record': {**record, 'status': status}}

record = {'learner_id': 'ana', 'status': 'started'}
assert edit_status('ana', record, 'complete')['ok'] is True
assert edit_status('ben', record, 'complete')['ok'] is False
assert record['status'] == 'started'
